(() => {
  "use strict";

  const ink = "#39283e";
  const blank = "#fffaf0";
  const makeSvg = (body, viewBox = "0 0 48 40") =>
    `<svg viewBox="${viewBox}" aria-hidden="true" focusable="false" shape-rendering="crispEdges">${body}</svg>`;

  const palette = [
    ["Mel", "#efb638"], ["Coral", "#ed927f"], ["Lilás", "#b69bc8"],
    ["Folha", "#86a17a"], ["Céu", "#80b8bc"], ["Creme", "#f2deb1"]
  ];
  const areas = ["Girassol", "Lírio", "Folhas", "Laço"];
  const cardKey = "jardim-isabelly.cartao.v1";
  let sessionCard;
  const flowerGroup = (index, body) =>
    `<g class="cap-area" role="button" tabindex="0" data-area="${index}" aria-label="Pintar: ${areas[index]}" fill="${blank}"><title>${areas[index]}</title>${body}</g>`;

  function bouquet() {
    // Petals are drawn in steps so the outlines stay legible at phone size.
    const flower = flowerGroup(0, `
      <path d="M72 27h4v-8h5v-6h5v4h5v8h4v-6h6v-3h6v9h-3v8h8v-3h8v6h-4v6h-9v4h7v5h5v5h-11v-3h-8v9h-5v4h-6v-8h-4v-8h-4v8h-5v5h-5v-9h-3v-6h-9v3h-9v-6h5v-5h7v-4h-8v-5h-6v-6h10v2h7v-6h-3v-9h6v5h5z"/>
      <path fill="#985b45" d="M77 30h15v4h5v11h-5v4H77v-4h-4V34h4z"/>
      <path fill="#edb762" stroke="none" d="M79 34h3v3h-3zm7 4h3v3h-3zm-7 5h3v2h-3zm9-11h3v3h-3z"/> `);
    const lily = flowerGroup(1, `
      <path d="M136 34h-4v-9h-3v-8h-4v-5h7v5h6v6h4v-8h5V7h5v12h-3v14h5v-6h6v-5h9v6h-5v5h-6v8h-8v5h-7v5h-9v-5h-9v-5h-7v-7h-6v-8h9v4h8v4z"/>
      <path d="M140 42V30m0 10 7-13m-6 14-8-11" fill="none" stroke="#955a54"/>
      <path stroke="none" fill="#e3a231" d="M137 25h5v5h-5zm8-2h5v5h-5zm-16 3h5v5h-5z"/> `);
    const leaves = flowerGroup(2, `
      <path d="M94 78H83v-4H72v-5h-6v-6h-8v-7h13v3h9v4h8v5h6z"/>
      <path d="M114 78v-9h5v-6h7v-4h10v-4h13v6h-6v6h-7v4h-10v4h-7v3z"/>
      <path d="M69 62l21 11m28-1 22-12" fill="none" stroke="#73806d" stroke-width="1.2"/> `);
    const bow = flowerGroup(3, `
      <path d="M98 95h-6v-5H82v5h-4v8h4v4h8v-4h8l-8 10v5h7l8-14 8 11h6v-6l-8-8h8v3h8V94h-4v-5h-7v3h-7v3z"/>
      <path d="M98 93h10v10H98z"/> `);
    return `<svg class="cap-bouquet" viewBox="0 0 212 127" aria-label="Cartão com um buquê para colorir" role="group">
      <rect width="212" height="127" fill="#fff8e9"/>
      <g fill="none" stroke="#c1ada1" stroke-width="1.1">
        <path d="M6 17V6h13m174 0h13v11M6 110v11h13m174 0h13v-11"/>
        <path stroke-dasharray="2 3" d="M9 21v85m194-85v85"/>
      </g>
      <g fill="#dcb3aa"><path d="M28 27h2v-3h2v3h3v2h-3v3h-2v-3h-2zm145 44h2v-3h2v3h3v2h-3v3h-2v-3h-2z"/><path d="M42 87h3v3h-3zm137-45h3v3h-3zm-20 62h3v3h-3z"/></g>
      <g stroke="${ink}" stroke-width="1.8" stroke-linejoin="round">
        <path d="M84 45q8 26 21 50m35-50q-13 18-32 49" fill="none" stroke-width="5"/><path d="M84 45q8 26 21 50m35-50q-13 18-32 49" fill="none" stroke="#839075" stroke-width="2"/>
        ${leaves}${flower}${lily}
        <path fill="#dba67b" d="M71 73l22 5 12 5 22-6 10-3-12 18-15 25-8 4-12-23z"/>
        <path fill="#f1c79b" d="M72 73l33 10-10 8z"/><path fill="#eed1a9" d="M137 74l-31 9 10 8z"/>
        <path d="M96 92l7 23m13-23-10 22" fill="none" stroke="#b28067" stroke-width="1.3"/>
        ${bow}
      </g></svg>`;
  }

  function downloadCard(svg) {
    const copy = svg.cloneNode(true);
    copy.removeAttribute("class");
    copy.setAttribute("width", "1060");
    copy.setAttribute("height", "635");
    copy.setAttribute("role", "img");
    copy.setAttribute("aria-label", "Buquê da Isabelly");
    copy.querySelectorAll("[data-area]").forEach(area => {
      for (const attribute of ["class", "role", "tabindex", "data-area", "aria-label"]) area.removeAttribute(attribute);
    });
    const link = document.createElement("a");
    link.download = "buque-da-isabelly.svg";
    link.href = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(new XMLSerializer().serializeToString(copy));
    document.body.append(link);
    link.click();
    link.remove();
  }

  function pintura(container, onWin) {
    let chosen = 0;
    const painted = new Map();
    let finished = false;
    const wrapper = document.createElement("section");
    wrapper.className = "cap-game cap-paint";
    wrapper.setAttribute("aria-label", "Oficina de pintura");
    wrapper.innerHTML = `<p class="cap-directions">Escolha uma tinta e toque no desenho para colorir seu buquê.</p>
      <div class="cap-art">${bouquet()}</div>
      <div class="cap-tools"><span class="cap-eyebrow">TINTAS</span><div class="cap-swatches" role="group" aria-label="Cores de tinta">${palette.map(([name, color], i) =>
        `<button type="button" class="cap-swatch" style="--tinta:${color}" data-color="${i}" aria-label="${name}" title="${name}" aria-pressed="${i === 0}"><span aria-hidden="true">✓</span></button>`).join("")}</div><span class="cap-color-name">Mel</span></div>
      <div class="cap-areas" role="group" aria-label="Partes do cartão para pintar">${areas.map((name, i) => `<button type="button" data-paint="${i}" aria-label="Colorir ${name}"><i aria-hidden="true"></i>${name}</button>`).join("")}</div>
      <div class="cap-bottom"><p class="cap-state" role="status">0 de 4 partes coloridas</p><div class="cap-actions"><button type="button" class="cap-download" hidden>Baixar cartão</button><button type="button" class="cap-continue" disabled>Guardar cartão <span aria-hidden="true">→</span></button></div></div>`;
    container.replaceChildren(wrapper);
    const done = wrapper.querySelector(".cap-continue");
    const download = wrapper.querySelector(".cap-download");
    const status = wrapper.querySelector(".cap-state");
    function paint(index, colorIndex = chosen) {
      if (finished) return;
      const [name, color] = palette[colorIndex];
      painted.set(index, colorIndex);
      const area = wrapper.querySelector(`[data-area="${index}"]`);
      area.setAttribute("fill", color);
      area.setAttribute("aria-label", `${areas[index]}, cor ${name}. Pintar novamente`);
      const chip = wrapper.querySelector(`[data-paint="${index}"]`);
      chip.style.setProperty("--marca", color);
      chip.classList.add("cap-painted");
      chip.setAttribute("aria-label", `${areas[index]}, cor ${name}. Pintar novamente`);
      done.disabled = painted.size !== areas.length;
      download.hidden = done.disabled;
      status.textContent = done.disabled
        ? `${painted.size} de 4 partes coloridas`
        : "Buquê pronto para guardar!";
    }
    let saved = sessionCard;
    try {
      const stored = !saved && localStorage.getItem(cardKey);
      if (stored) saved = JSON.parse(stored);
    } catch { /* File-based browsers may restrict local storage. */ }
    if (Array.isArray(saved) && saved.length === areas.length &&
        saved.every(value => Number.isInteger(value) && value >= 0 && value < palette.length)) {
      saved.forEach((value, index) => paint(index, value));
      status.textContent = "Seu cartão guardado. Quer mudar alguma cor?";
    }
    wrapper.querySelectorAll("[data-color]").forEach(button => {
      button.addEventListener("click", () => {
        chosen = Number(button.dataset.color);
        wrapper.querySelectorAll("[data-color]").forEach(other => other.setAttribute("aria-pressed", String(button === other)));
        wrapper.querySelector(".cap-color-name").textContent = palette[chosen][0];
      });
    });
    wrapper.querySelectorAll("[data-area]").forEach(area => {
      area.addEventListener("click", () => paint(Number(area.dataset.area)));
      area.addEventListener("keydown", event => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          paint(Number(area.dataset.area));
        }
      });
    });
    wrapper.querySelectorAll("[data-paint]").forEach(chip => chip.addEventListener("click", () => paint(Number(chip.dataset.paint))));
    download.addEventListener("click", () => {
      if (painted.size === areas.length) downloadCard(wrapper.querySelector(".cap-bouquet"));
    });
    done.addEventListener("click", () => {
      if (finished || painted.size !== areas.length) return;
      finished = true;
      done.disabled = true;
      sessionCard = areas.map((_, index) => painted.get(index));
      try { localStorage.setItem(cardKey, JSON.stringify(sessionCard)); }
      catch { /* The active session still retains the card. */ }
      onWin();
    });
  }

  const illustrations = [
    {
      title: "Coração", tint: "#f4d5dc",
      art: makeSvg('<use href="#coracao" color="#bf6679"></use>', "0 0 13 12")
    },
    {
      title: "Corinthians", tint: "#e9e5d9",
      // Imagem incorporada para funcionar sem uma requisição separada ao arquivo.
      // Crédito e licença do escudo em assets/CREDITOS.md.
      art: '<img src="data:image/png;base64," alt="" width="78" height="66">'
    },
    {
      title: "Girassol", tint: "#f9dfb6",
      art: makeSvg('<use href="#flor"></use>', "0 0 32 32")
    },
    {
      title: "Lírio", tint: "#dbe6cb",
      art: makeSvg('<use href="#lirio"></use>', "0 0 32 32")
    }
  ];

  const cardBack = makeSvg(`<path d="M22 7h4v7h4v3h7v4h-7v4h-4v7h-4v-7h-4v-4h-7v-4h7v-3h4z" fill="#f8d985"/><path d="M23 16h3v6h-3zM9 7h3v3H9zm26 21h3v3h-3z" fill="#f9e9bd"/>`);

  function cinema(container, onWin) {
    const totalPairs = illustrations.length;
    const order = illustrations.flatMap((_, id) => [id, id]);
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    const wrapper = document.createElement("section");
    wrapper.className = "cap-game cap-memory";
    wrapper.setAttribute("aria-label", "Jogo da memória");
    wrapper.innerHTML = `<p class="cap-directions">Vire duas cartas por vez. Encontre os ${totalPairs} pares para revelar seu bilhete.</p>
      <div class="cap-memory-grid">${order.map((id, i) => {
        const item = illustrations[id];
        return `<button type="button" class="cap-card" style="--face:${item.tint}" aria-label="Virar carta ${i + 1}"><span class="cap-card-back" aria-hidden="true"><small>0${i + 1}</small>${cardBack}</span><span class="cap-card-front" aria-hidden="true">${item.art}<b>${item.title}</b></span></button>`;
      }).join("")}</div><div class="cap-bottom"><p class="cap-state" role="status">0 de ${totalPairs} pares</p><button type="button" class="cap-continue" hidden>Abrir bilhete <span aria-hidden="true">→</span></button></div>`;
    container.replaceChildren(wrapper);
    let first = null;
    let busy = false;
    let pairs = 0;
    let finished = false;
    const status = wrapper.querySelector(".cap-state");
    const done = wrapper.querySelector(".cap-continue");
    const cards = [...wrapper.querySelectorAll(".cap-card")];
    function cover(i) {
      cards[i].classList.remove("cap-up");
      cards[i].setAttribute("aria-label", `Virar carta ${i + 1}`);
    }
    cards.forEach((card, i) => card.addEventListener("click", () => {
      if (busy || card.classList.contains("cap-up")) return;
      const title = illustrations[order[i]].title;
      card.classList.add("cap-up");
      card.setAttribute("aria-label", `Carta ${i + 1}: ${title}`);
      if (first === null) {
        first = i;
        status.textContent = `${title}. Escolha outra carta.`;
        return;
      }
      const other = first;
      first = null;
      if (order[i] === order[other]) {
        pairs++;
        for (const index of [i, other]) {
          cards[index].classList.add("cap-paired");
          cards[index].setAttribute("aria-disabled", "true");
          cards[index].setAttribute("aria-label", `${title}, par encontrado`);
        }
        status.textContent = pairs === totalPairs ? "Todos os pares! Seu bilhete está pronto." : `Par de ${title}! ${pairs} de ${totalPairs} pares.`;
        if (pairs === totalPairs) done.hidden = false;
      } else {
        busy = true;
        status.textContent = `${illustrations[order[other]].title} e ${title}. Tente de novo!`;
        setTimeout(() => {
          if (!wrapper.isConnected) return;
          cover(other);
          cover(i);
          busy = false;
          status.textContent = `${pairs} de ${totalPairs} pares`;
        }, 1500);
      }
    }));
    done.addEventListener("click", () => {
      if (pairs !== totalPairs || finished) return;
      finished = true;
      done.disabled = true;
      onWin();
    });
  }
  window.Capitulos = { pintura, cinema, totalPares: illustrations.length };
})();
